use system.fs
use system.text
use system.collections.list
use system.collections.map

fn add_word(counts Map<String, int>, word String)
    match counts.get(word)
        Some(n): counts.set(word, n + 1)
        None: counts.set(word, 1)

// A word is a maximal run of ASCII letters and digits; every other byte separates words.
