use system.os
use system.fs
use system.text
use system.collections.list
use system.collections.map

fn add_word(counts Map<String, int>, word String)
    match counts.get(word)
        Some(n): counts.set(word, n + 1)
        None: counts.set(word, 1)

// A word is a maximal run of ASCII letters and digits; every other byte separates words.
fn count_words(text String) Map<String, int>
    var counts = Map<String, int>()
    let words = match Regex.compile("[A-Za-z0-9]+")
        Result.Ok(re): re
        Result.Err(e): panic("cannot compile word pattern")
    for m in words.find_all(text)
        add_word(counts, m.text().to_lower())
    counts

// True when `a` (with count `ca`) ranks before `b` (with count `cb`).
fn ranks_before(a String, ca int, b String, cb int) bool
    if ca != cb
        return ca > cb
    a.compare(b) < 0

